WITH parsed AS (SELECT id, plan, tier_limits, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT id, plan, entry_price, AVG(entry_price) OVER (ORDER BY entry_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) entry_price_avg_2, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY entry_price DESC, id) event_seq, SUM(entry_price) OVER (PARTITION BY plan ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_entry_price FROM parsed;
